#include <openssl/hmac.h>
#include <openssl/rand.h>
#include <openssl/evp.h>
#include <string>
#include <vector>
#include <unordered_map>
#include <chrono>
#include <mutex>
#include <memory>
#include <cstring>

namespace auth {

struct ServiceIdentity {
    std::string service_name;
    std::string realm;
    uint32_t trust_level;
};

class KeyDerivationContext {
private:
    unsigned char master_secret_[32];
    std::string domain_separator_;

public:
    KeyDerivationContext(const unsigned char* master, const std::string& domain)
        : domain_separator_(domain) {
        memcpy(master_secret_, master, 32);
    }

    std::vector<unsigned char> derive_service_key(
        const ServiceIdentity& identity,
        const std::string& purpose) const {

        std::vector<unsigned char> derived(32);
        std::string context = domain_separator_ + ":" + 
                             identity.service_name + ":" + purpose;

        unsigned int len = 32;
        HMAC(EVP_sha256(), master_secret_, 32,
             reinterpret_cast<const unsigned char*>(context.c_str()),
             context.length(), derived.data(), &len);

        return derived;
    }
};

class TokenGenerator {
private:
    std::vector<unsigned char> signing_key_;
    std::string issuer_;

public:
    TokenGenerator(const std::vector<unsigned char>& key, const std::string& issuer)
        : signing_key_(key), issuer_(issuer) {}

    std::vector<unsigned char> generate_token(
        const std::string& subject,
        uint64_t expiry_ts) const {

        std::string payload = issuer_ + "|" + subject + "|" + 
                             std::to_string(expiry_ts);

        std::vector<unsigned char> token(32);
        unsigned int len = 32;
        HMAC(EVP_sha256(), signing_key_.data(), signing_key_.size(),
             reinterpret_cast<const unsigned char*>(payload.c_str()),
             payload.length(), token.data(), &len);

        return token;
    }
};

class CrossServiceAuthenticator {
private:
    std::unique_ptr<KeyDerivationContext> kdc_;
    std::unordered_map<std::string, std::unique_ptr<TokenGenerator>> generators_;
    std::mutex mu_;
    ServiceIdentity self_identity_;

    static constexpr char PURPOSE_SIGNING[] = "token-signing";
    static constexpr char PURPOSE_VERIFY[] = "token-verification";

public:
    CrossServiceAuthenticator(
        const unsigned char* master_key,
        const ServiceIdentity& identity,
        const std::string& domain)
        : self_identity_(identity) {

        kdc_ = std::make_unique<KeyDerivationContext>(master_key, domain);

        auto signing_key = kdc_->derive_service_key(identity, PURPOSE_SIGNING);
        generators_[identity.service_name] = 
            std::make_unique<TokenGenerator>(signing_key, identity.service_name);
    }

    std::vector<unsigned char> issue_cross_service_token(
        const ServiceIdentity& target_service,
        const std::string& subject,
        uint64_t validity_seconds) {

        std::lock_guard<std::mutex> lock(mu_);

        auto now = std::chrono::system_clock::now();
        uint64_t expiry = std::chrono::duration_cast<std::chrono::seconds>(
            now.time_since_epoch()).count() + validity_seconds;

        auto& gen = get_or_create_generator(target_service);
        return gen.generate_token(subject, expiry);
    }

    bool verify_incoming_token(
        const ServiceIdentity& claiming_source,
        const std::string& subject,
        uint64_t claimed_expiry,
        const std::vector<unsigned char>& token) {

        std::lock_guard<std::mutex> lock(mu_);

        auto now = std::chrono::system_clock::now();
        uint64_t current_ts = std::chrono::duration_cast<std::chrono::seconds>(
            now.time_since_epoch()).count();

        if (claimed_expiry < current_ts) {
            return false;
        }

        auto verification_key = kdc_->derive_service_key(
            self_identity_, PURPOSE_SIGNING);

        TokenGenerator verifier(verification_key, claiming_source.service_name);
        auto expected = verifier.generate_token(subject, claimed_expiry);

        return CRYPTO_memcmp(expected.data(), token.data(), 32) == 0;
    }

private:
    TokenGenerator& get_or_create_generator(const ServiceIdentity& target) {
        auto it = generators_.find(target.service_name);
        if (it != generators_.end()) {
            return *(it->second);
        }

        // Key derivation uses target's identity but same purpose
        // This creates the cross-service authentication binding
        auto key = kdc_->derive_service_key(target, PURPOSE_SIGNING);
        generators_[target.service_name] = 
            std::make_unique<TokenGenerator>(key, self_identity_.service_name);
        return *(generators_[target.service_name]);
    }
};

// Factory function for service initialization
std::unique_ptr<CrossServiceAuthenticator> create_authenticator(
    const unsigned char* shared_master_key,
    const std::string& service_name,
    const std::string& realm,
    uint32_t trust_level,
    const std::string& domain) {

    ServiceIdentity id{service_name, realm, trust_level};
    return std::make_unique<CrossServiceAuthenticator>(
        shared_master_key, id, domain);
}

} // namespace auth
